INSERT INTO `chat_ia_historial` (`id`, `sesion_id`, `usuario_id`, `username`, `rol`, `contenido`, `tipo`, `sql_usado`, `created_at`) VALUES
(1, 'sim-20260603-001', 1, 'admin', 'user', '¿Cuánto vendimos hoy?', 'texto', NULL, '2026-05-29 00:00:00'),
(2, 'sim-20260603-001', 1, 'admin', 'assistant', 'Hoy llevan $187,500 en 12 órdenes. El 60% en efectivo y 40% en nequi.', 'texto', NULL, '2026-05-29 00:00:00'),
(3, 'sim-20260603-001', 1, 'admin', 'user', '¿Qué productos se vendieron más?', 'texto', NULL, '2026-05-29 00:00:00'),
(4, 'sim-20260603-001', 1, 'admin', 'assistant', 'Las arepas de la casa lideran con 34 unidades este mes, seguidas del especial con pollo con 28.', 'texto', NULL, '2026-05-29 00:00:00'),
(5, 'sim-20260603-001', 1, 'admin', 'user', '¿Cómo va el stock?', 'texto', NULL, '2026-05-29 00:00:00'),
(6, 'sim-20260603-001', 1, 'admin', 'assistant', 'Tienes 3 insumos en stock bajo: harina de maíz (2kg, mínimo 5kg), queso costeño y aceite.', 'texto', NULL, '2026-05-29 00:00:00'),
(7, 'sim-20260603-001', 1, 'admin', 'user', 'Registra un gasto de $200000 en insumos', 'texto', NULL, '2026-05-29 00:00:00'),
(8, 'sim-20260603-001', 1, 'admin', 'assistant', 'Propuesta: INSERT INTO gastos... ¿Confirmas?', 'texto', NULL, '2026-05-29 00:00:00'),
(9, 'sim-20260603-001', 1, 'admin', 'user', '¿Cuál fue la mejor semana del mes?', 'texto', NULL, '2026-05-29 00:00:00'),
(10, 'sim-20260603-001', 1, 'admin', 'assistant', 'La semana del 15 al 21 fue la más activa con $2,340,000 en ventas y 89 órdenes.', 'texto', NULL, '2026-05-29 00:00:00');
